CREATE OR REPLACE FUNCTION mission_narrative_internal.native_peaceful_decision_v1(p_source jsonb,p_source_sha256 text,p_assessment jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path='' AS $function$
DECLARE src jsonb:=p_source;d jsonb:=p_assessment;x jsonb;pg jsonb;evq jsonb;seen text[]:='{}';all_accept boolean:=true;
BEGIN
 IF p_source_sha256 IS NULL OR p_source_sha256 IS DISTINCT FROM public.combat_v2_sha256(src) THEN RAISE EXCEPTION 'NATIVE_PEACEFUL_ASSESSMENT_SOURCE' USING ERRCODE='22023';END IF;
  IF NOT mission_factory_owner.keys_exact_v2(d,ARRAY['schema_version','source_sha256','agreement_source_declaration_id','agreement_quote','pg_interpretations','png_decisions'])
   OR d->>'schema_version'<>'mission-native-peaceful-assessment/1' OR d->>'source_sha256'<>p_source_sha256
   OR jsonb_typeof(d->'pg_interpretations')<>'array' OR jsonb_typeof(d->'png_decisions')<>'array'
   OR jsonb_array_length(d->'pg_interpretations')<>jsonb_array_length(src->'pg_sources')
   OR jsonb_array_length(d->'png_decisions')<>jsonb_array_length(src->'png_profiles')
  THEN RAISE EXCEPTION 'NATIVE_PEACEFUL_ASSESSMENT_SOURCE' USING ERRCODE='22023';END IF;
  FOR x IN SELECT value FROM jsonb_array_elements(d->'pg_interpretations') LOOP
   SELECT value INTO pg FROM jsonb_array_elements(src->'pg_sources') WHERE value->>'actor_id'=x->>'actor_id' AND value->>'user_id'=x->>'user_id';
   IF NOT mission_factory_owner.keys_exact_v2(x,ARRAY['actor_id','user_id','intent','evidence']) OR pg IS NULL
    OR x->>'actor_id'=ANY(seen) OR x->>'intent' IS NULL OR x->>'intent' NOT IN('cease','continue','undetermined') OR jsonb_typeof(x->'evidence')<>'array'
    OR(x->>'intent'<>'undetermined' AND jsonb_array_length(x->'evidence')=0) THEN RAISE EXCEPTION 'NATIVE_PEACEFUL_PG_EVIDENCE' USING ERRCODE='22023';END IF;
   seen:=array_append(seen,x->>'actor_id');all_accept:=all_accept AND x->>'intent'='cease';
   FOR evq IN SELECT value FROM jsonb_array_elements(x->'evidence') LOOP
    IF NOT mission_factory_owner.keys_exact_v2(evq,ARRAY['declaration_id','quote']) OR evq->>'declaration_id'<>pg->>'declaration_id'
     OR jsonb_typeof(evq->'quote')<>'string' OR length(evq->>'quote')=0 OR position(evq->>'quote' in pg->>'body')=0
    THEN RAISE EXCEPTION 'NATIVE_PEACEFUL_PG_QUOTE' USING ERRCODE='22023';END IF;
   END LOOP;
  END LOOP;
  seen:='{}';
  FOR x IN SELECT value FROM jsonb_array_elements(d->'png_decisions') LOOP
   IF NOT mission_factory_owner.keys_exact_v2(x,ARRAY['actor_id','intent']) OR x->>'actor_id'=ANY(seen)
    OR x->>'intent' IS NULL OR x->>'intent' NOT IN('accept','refuse','undetermined') OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(src->'png_profiles') p WHERE p->>'actor_id'=x->>'actor_id')
   THEN RAISE EXCEPTION 'NATIVE_PEACEFUL_PNG_DECISION' USING ERRCODE='22023';END IF;
   seen:=array_append(seen,x->>'actor_id');all_accept:=all_accept AND x->>'intent'='accept';
  END LOOP;
  IF d->'agreement_source_declaration_id'='null'::jsonb THEN
   IF d->>'agreement_quote'<>'' THEN RAISE EXCEPTION 'NATIVE_PEACEFUL_AGREEMENT_SOURCE' USING ERRCODE='22023';END IF;
   all_accept:=false;
  ELSE
   SELECT value INTO pg FROM jsonb_array_elements(src->'pg_sources') WHERE value->>'declaration_id'=d->>'agreement_source_declaration_id';
   IF pg IS NULL OR jsonb_typeof(d->'agreement_quote')<>'string' OR length(d->>'agreement_quote')=0 OR position(d->>'agreement_quote' in pg->>'body')=0
   THEN RAISE EXCEPTION 'NATIVE_PEACEFUL_AGREEMENT_QUOTE' USING ERRCODE='22023';END IF;
  END IF;
 RETURN jsonb_build_object('assessment',d,'close_eligible',all_accept,'writer_next_step',CASE WHEN all_accept THEN src->>'writer_next_step' ELSE 'stay' END);
END $function$;

CREATE OR REPLACE FUNCTION mission_narrative_internal.native_peaceful_commit_v1(p_work uuid, p_result jsonb, p_message uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE w mission_generic_owner.work_items;parent mission_generic_owner.work_items;r mission_narrative_internal.scene_runtime_v1;
 run public.mission_run_state;b mission_generic_owner.run_bindings;m public.master_v2_sessions;enc mission_generic_owner.encounters;
 srcrow mission_narrative_internal.scene_sources_v1;root mission_generic_owner.event_outbox_v1;
 src jsonb;fresh jsonb;d jsonb;x jsonb;pg jsonb;evq jsonb;receipt jsonb;payload jsonb;sha text;sid uuid;wid uuid;
 all_accept boolean:=true;who text;seen text[]:='{}';n integer;req jsonb;cfg jsonb;ek uuid;wake bigint;
 begin_event jsonb;closed jsonb;transition jsonb;cev public.combat_v2_events;step text;msg public.messages;encounter26 uuid;
BEGIN
 PERFORM mission_ai_board_owner.service_only();
 SELECT * INTO STRICT w FROM mission_generic_owner.work_items WHERE id=p_work FOR UPDATE;
 PERFORM public.master_v2_lock_scope(w.master_session_id);
 SELECT * INTO STRICT r FROM mission_narrative_internal.scene_runtime_v1 WHERE master_session_id=w.master_session_id AND is_active FOR UPDATE;
 SELECT * INTO STRICT run FROM public.mission_run_state WHERE master_session_id=w.master_session_id FOR UPDATE;
 SELECT * INTO STRICT b FROM mission_generic_owner.run_bindings WHERE master_session_id=w.master_session_id;
 SELECT * INTO STRICT m FROM public.master_v2_sessions WHERE id=w.master_session_id FOR UPDATE;
 IF w.state<>'provider_started' OR w.lease_expires_at<=clock_timestamp() OR w.payload_sha256<>public.combat_v2_sha256(w.payload)
  OR w.step_key<>run.current_step_key OR w.run_control_version<>run.control_version OR p_result->'ok' IS DISTINCT FROM 'true'::jsonb
 THEN RAISE EXCEPTION 'NATIVE_PEACEFUL_WORK_CHANGED' USING ERRCODE='PT409';END IF;
 IF w.kind='director' AND w.payload->>'schema_version'='mission-native-peaceful-assessment/1' THEN
  src:=w.payload->'source';d:=p_result->'decision';
  PERFORM public.combat_v2_lock_round((src->>'empty_round_id')::uuid);
  fresh:=mission_narrative_internal.native_peaceful_source_v1(m.id,(src->>'empty_round_id')::uuid);
  IF fresh IS DISTINCT FROM src OR public.combat_v2_sha256(src) IS DISTINCT FROM w.payload->>'source_sha256' THEN RAISE EXCEPTION 'NATIVE_PEACEFUL_ASSESSMENT_SOURCE' USING ERRCODE='22023';END IF;
  all_accept:=(mission_narrative_internal.native_peaceful_decision_v1(src,w.payload->>'source_sha256',d)->>'close_eligible')::boolean;
  receipt:=jsonb_build_object('schema_version','mission-native-peaceful-decision-receipt/1','source',src,'source_sha256',w.payload->>'source_sha256',
   'assessment_work_id',w.id,'assessment',d,'close_eligible',all_accept,'writer_next_step',CASE WHEN all_accept THEN src->>'writer_next_step' ELSE 'stay' END);
  sha:=public.combat_v2_sha256(jsonb_build_object('scene',r.id,'state_version',r.state_version,'receipt',receipt,'last_publication',r.last_publication_id));
  sid:=mission_ai_service_owner.uuid5(w.id,'peaceful-writer-source:'||sha);wid:=mission_ai_service_owner.uuid5(sid,'narrative-work');
  IF EXISTS(SELECT 1 FROM mission_generic_owner.work_items nw WHERE nw.id=wid) THEN RETURN jsonb_build_object('state','narration_ready','work_id',wid,'peaceful',all_accept,'replayed',true);END IF;
  payload:=jsonb_build_object('schema_version','mission-narrative-scene/1','mode','narrative_scene','scene_id',r.id,
   'source_window_id',sid,'source_revision',sha,'state_version',r.state_version,'snapshot_sha256',r.snapshot_sha256,'snapshot',r.snapshot,
   'current_phase_key',r.current_phase_key,'scene_memory',r.scene_memory,'accepted_roles','[]'::jsonb,
   'last_publication',jsonb_build_object('message_id',r.last_publication_id,'body_sha256',r.last_publication_sha256),'last_fati',r.last_fati,'combat_peaceful',receipt);
  SELECT * INTO STRICT root FROM mission_generic_owner.event_outbox_v1 WHERE master_session_id=m.id AND event_domain='start' AND event_version=1;
  INSERT INTO mission_narrative_internal.scene_sources_v1(id,scene_id,work_id,actor_user_id,state_version,source_revision,snapshot_sha256,
   accepted_role_ids,accepted_roles_sha256,last_publication_id,last_publication_sha256,current_phase_key,scene_memory_sha256,payload_sha256,request_kind,technical_request)
  VALUES(sid,r.id,wid,root.root_principal,r.state_version,sha,r.snapshot_sha256,'{}'::uuid[],public.combat_v2_sha256('[]'::jsonb),
   r.last_publication_id,r.last_publication_sha256,r.current_phase_key,public.combat_v2_sha256(coalesce(r.scene_memory,'null'::jsonb)),public.combat_v2_sha256(payload),'combat_peaceful',receipt);
  INSERT INTO mission_generic_owner.work_items(id,master_session_id,event_id,dedupe_key,step_key,run_control_version,definition_sha256,encounter_id,authority_receipt_id,kind,revision,payload,payload_sha256)
  VALUES(wid,m.id,sid,'narrative:'||sid,run.current_step_key,run.control_version,b.snapshot_sha256,NULL,sid,'narration',run.control_version,payload,public.combat_v2_sha256(payload));
  -- Contract is issued by the normal claim after the parent finalizer commits its decision.
  SELECT canonical_preimage::jsonb#>'{config,c1266_server_events}' INTO cfg FROM mission_factory_owner.editor_release_readiness
   WHERE singleton AND state='enabled' AND scope='staff' AND revision_sha256=observed_revision_sha256;
  IF cfg->>'schema_version'<>'c1266-server-events/1' OR cfg->'enabled' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'NATIVE_PEACEFUL_WAKE_SCOPE' USING ERRCODE='42501';END IF;
  SELECT jsonb_build_object('schema_version','mission-generic-request/1','master_session_id',m.id,'event_id',nw.event_id,'request_key',nw.request_key,'expected_revision',nw.revision)
   INTO req FROM mission_generic_owner.work_items nw WHERE nw.id=wid;
  ek:=mission_ai_service_owner.uuid5(wid,'server-event:writer-ready');
  INSERT INTO mission_generic_owner.event_outbox_v1(event_key,event_version,master_session_id,event_domain,source_id,source_sha256,root_event_key,root_request_key,root_principal,root_receipt_sha256,work_id,canonical_request)
  VALUES(ek,1,m.id,'writer_ready',wid,public.combat_v2_sha256(payload),root.root_event_key,root.root_request_key,root.root_principal,root.root_receipt_sha256,wid,req);
  wake:=net.http_post(cfg->>'endpoint',jsonb_build_object('schema_version','mission-event-wake/2','event_key',ek,'event_version',1),'{}'::jsonb,jsonb_build_object('Content-Type','application/json','x-tus-server-event','event42'),5000);
  UPDATE mission_generic_owner.event_outbox_v1 SET wake_request_id=wake WHERE event_key=ek AND event_version=1;
  RETURN jsonb_build_object('state','narration_ready','work_id',wid,'peaceful',all_accept,'replayed',false);
 END IF;
 IF w.kind<>'narration' OR w.payload->>'schema_version'<>'mission-narrative-scene/1' OR p_message IS NULL THEN RAISE EXCEPTION 'NATIVE_PEACEFUL_COMMIT_KIND' USING ERRCODE='22023';END IF;
 receipt:=w.payload->'combat_peaceful';src:=receipt->'source';encounter26:=(src->>'encounter_id')::uuid;
 SELECT * INTO STRICT srcrow FROM mission_narrative_internal.scene_sources_v1 WHERE work_id=w.id AND request_kind='combat_peaceful' FOR UPDATE;
 SELECT * INTO STRICT parent FROM mission_generic_owner.work_items WHERE id=(receipt->>'assessment_work_id')::uuid;
 SELECT * INTO STRICT msg FROM public.messages WHERE id=p_message AND location_id=m.location_id AND kind='fato' AND recipient_user IS NULL;
 PERFORM public.combat_v2_lock_round((src->>'empty_round_id')::uuid);
 fresh:=mission_narrative_internal.native_peaceful_source_v1(m.id,(src->>'empty_round_id')::uuid);
 IF parent.kind<>'director' OR parent.state<>'completed' OR parent.master_session_id<>m.id
  OR parent.payload->>'schema_version'<>'mission-native-peaceful-assessment/1' OR parent.result->'ok' IS DISTINCT FROM 'true'::jsonb
  OR parent.payload_sha256 IS DISTINCT FROM public.combat_v2_sha256(parent.payload) OR parent.encounter_id IS DISTINCT FROM encounter26
  OR parent.payload->'source' IS DISTINCT FROM src OR parent.payload->>'source_sha256' IS DISTINCT FROM receipt->>'source_sha256'
  OR parent.result->'decision' IS DISTINCT FROM receipt->'assessment' OR srcrow.technical_request IS DISTINCT FROM receipt
  OR fresh IS DISTINCT FROM src OR msg.body IS DISTINCT FROM p_result->>'text' OR p_result#>>'{scene_update,next_step}' IS DISTINCT FROM receipt->>'writer_next_step'
 THEN RAISE EXCEPTION 'NATIVE_PEACEFUL_COMMIT_SOURCE' USING ERRCODE='PT409';END IF;
 IF receipt->'close_eligible' IS DISTINCT FROM 'true'::jsonb THEN RETURN jsonb_build_object('closed',false,'transition',null,'route_step_key',run.current_step_key,'run_control_version',run.control_version);END IF;
 SELECT * INTO STRICT enc FROM mission_generic_owner.encounters WHERE encounter_id=encounter26 AND master_session_id=m.id;
 begin_event:=public.combat_v2_event_begin_ai_service(m.id,mission_ai_service_owner.uuid5(w.id,'native-peaceful-close'),
  'mission_generic_combat_close_peaceful',jsonb_build_object('encounter_id',encounter26,'source_report_id',src->>'source_report_id',
   'empty_round_id',src->>'empty_round_id','assessment_work_id',parent.id,'publication_message_id',msg.id,'run_version',run.control_version),m.control_version,enc.capability_id);
 IF (begin_event->>'replay')::boolean THEN RAISE EXCEPTION 'NATIVE_PEACEFUL_UNEXPECTED_CLOSE_REPLAY' USING ERRCODE='PT409';END IF;
 UPDATE public.combat_v2_sessions SET state='chiuso',closed_at=clock_timestamp() WHERE id=encounter26 AND closed_at IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'NATIVE_PEACEFUL_CLOSE_CAS' USING ERRCODE='PT409';END IF;
 closed:=public.combat_v2_envelope(mission_ai_service_owner.uuid5(w.id,'native-peaceful-close'),jsonb_build_object('encounter_id',encounter26,'state','chiuso','closure_kind','peaceful',
  'master_session_id',m.id,'step_key',run.current_step_key,'encounter_key',enc.encounter_key,'run_version',run.control_version,
  'terminal_event_id',begin_event->>'event_id','unused_successor_round_id',src->>'empty_round_id',
  'assessment_work_id',parent.id,'publication_message_id',msg.id,'route_sha256',public.combat_v2_sha256(src->'terminal_routes'->0)));
 closed:=public.combat_v2_event_complete((begin_event->>'event_id')::uuid,closed);
 SELECT * INTO STRICT cev FROM public.combat_v2_events WHERE id=(begin_event->>'event_id')::uuid;
 transition:=mission_generic_owner.apply_authority(m.id,mission_ai_service_owner.uuid5(cev.id,'generic-peaceful-transition'),
  m.control_version,run.control_version,src#>>'{terminal_routes,0,trigger_key}','combat_terminal',cev.id,public.combat_v2_sha256(to_jsonb(cev)),null);
 SELECT * INTO STRICT run FROM public.mission_run_state WHERE master_session_id=m.id;
 IF 'scene:'||run.current_step_key IS DISTINCT FROM receipt->>'writer_next_step' THEN RAISE EXCEPTION 'NATIVE_PEACEFUL_ROUTE_TARGET' USING ERRCODE='PT409';END IF;
 UPDATE mission_narrative_internal.scene_sources_v1 SET technical_receipt=jsonb_build_object('schema_version','mission-native-peaceful-publication/1',
  'message_id',msg.id,'assessment_work_id',parent.id,'terminal_event_id',cev.id,'transition',transition,'unused_successor_round_id',src->>'empty_round_id') WHERE id=srcrow.id;
 RETURN jsonb_build_object('closed',true,'transition',transition,'event_id',cev.id,'route_step_key',run.current_step_key,'run_control_version',run.control_version);
END $function$

