CREATE OR REPLACE FUNCTION public.mission_staff_editorial_step_v1(p_user uuid, p_run uuid, p_worker_token text, p_command jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r mission_narrative_internal.editorial_runs_v1;c mission_narrative_internal.editorial_campaigns_v1;pol jsonb;op text;cost numeric;base_cost numeric;http_used bigint;
 env jsonb;fp text;authsha text;qr jsonb;core jsonb;cnt integer;aid uuid;dr mission_narrative_internal.dispatch_receipts;
 z mission_narrative_internal.provider_authorizations;att mission_narrative_internal.dispatch_attempts;it integer;ot integer;rt integer;outcome text;doc jsonb;rs text;changed boolean:=false;overflow boolean:=false;ch integer:=0;gh integer:=0;why text;count_q staff_ai_quota_private.calls;gen_q staff_ai_quota_private.calls;
BEGIN
 IF auth.uid() IS NOT NULL OR NOT public.combat_v2_is_service() THEN RAISE EXCEPTION 'E65_SERVICE_REQUIRED' USING ERRCODE='42501';END IF;
 PERFORM mission_narrative_internal.worker(p_worker_token);
 SELECT * INTO STRICT r FROM mission_narrative_internal.editorial_runs_v1 WHERE id=p_run AND actor_user=p_user;
 SELECT * INTO STRICT c FROM mission_narrative_internal.editorial_campaigns_v1 WHERE id=r.campaign_id FOR UPDATE;
 SELECT * INTO STRICT r FROM mission_narrative_internal.editorial_runs_v1 WHERE id=p_run FOR UPDATE;
 op:=p_command->>'operation';
 IF op IN('retain','finish','reconcile') THEN
  IF r.policy_sha256<>public.combat_v2_sha256(r.policy_snapshot) OR r.source_sha256<>public.combat_v2_sha256(r.source) THEN RAISE EXCEPTION 'E65_FROZEN_CLOSING_DRIFT';END IF;
  IF r.receipt_id IS NOT NULL THEN pol:=mission_narrative_internal.editorial_authority_v1(p_user,c.id,r.receipt_id,true);ELSE pol:=r.policy_snapshot->'policy';END IF;
 ELSE pol:=mission_narrative_internal.editorial_authority_v1(p_user,c.id,r.receipt_id);END IF;
 IF jsonb_typeof(p_command)<>'object' OR op NOT IN('count_start','count_result','authorize','consume','retain','finish','reject','reconcile') THEN RAISE EXCEPTION 'E65_OPERATION_INVALID';END IF;
 IF op NOT IN('retain','finish','reconcile') AND clock_timestamp()>(pol->>'close_deadline')::timestamptz THEN RAISE EXCEPTION 'E65_CLOSE_WINDOW_EXPIRED';END IF;
 IF op IN('count_start','authorize','consume') AND (clock_timestamp()>(pol->>'provider_deadline')::timestamptz OR r.variant IS DISTINCT FROM
  (SELECT canonical_preimage::jsonb#>>'{config,c1266_editorial65,active_variant}' FROM mission_factory_owner.editor_release_readiness WHERE singleton)) THEN RAISE EXCEPTION 'E65_PROVIDER_WINDOW_EXPIRED_OR_VARIANT';END IF;
 SELECT coalesce(sum(CASE WHEN state IN('settled','over_cap') THEN charged_usd WHEN state='no_http' THEN 0 ELSE reserved_usd END),0),count(*) FILTER(WHERE state<>'no_http')
  INTO cost,http_used FROM staff_ai_quota_private.calls WHERE producer='mission_editorial_preview' AND scope_id=c.id;
 SELECT coalesce(sum(CASE WHEN q.state IN('settled','over_cap') THEN q.charged_usd WHEN q.state='no_http' THEN 0 ELSE q.reserved_usd END),0) INTO base_cost
  FROM staff_ai_quota_private.calls q WHERE q.scope_id IN(SELECT value::uuid FROM jsonb_array_elements_text(pol->'history_scope_ids'));
 IF op='reconcile' THEN
  IF NOT mission_factory_owner.keys_exact_v2(p_command,ARRAY['operation']) THEN RAISE EXCEPTION 'E65_RECONCILE_SHAPE';END IF;
  IF r.count_call_id IS NOT NULL THEN SELECT * INTO STRICT count_q FROM staff_ai_quota_private.calls WHERE id=r.count_call_id AND producer='mission_editorial_preview' AND source_id=r.receipt_id AND scope_id=r.campaign_id AND call_no=2;ch:=CASE WHEN count_q.state IN('sent','settled','over_cap','unknown_billable') THEN 1 ELSE 0 END;END IF;
  IF r.generation_call_id IS NOT NULL THEN SELECT * INTO STRICT gen_q FROM staff_ai_quota_private.calls WHERE id=r.generation_call_id AND producer='mission_editorial_preview' AND source_id=r.receipt_id AND scope_id=r.campaign_id AND call_no=1;gh:=CASE WHEN gen_q.state IN('sent','settled','over_cap','unknown_billable') THEN 1 ELSE 0 END;END IF;
  IF r.receipt_id IS NOT NULL THEN SELECT * INTO STRICT dr FROM mission_narrative_internal.dispatch_receipts WHERE id=r.receipt_id FOR UPDATE;END IF;
  IF r.state NOT IN('completed','failed','uncertain') THEN
   IF r.state='ready' AND r.created_at<=clock_timestamp()-interval '180 seconds' AND r.receipt_id IS NULL AND r.count_call_id IS NULL AND r.generation_call_id IS NULL
    AND r.request_sha256 IS NULL AND NOT EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_receipts WHERE authority_receipt_id=r.id)
   THEN why:='READY_EXPIRED_NO_HTTP';changed:=true;ch:=0;gh:=0;
   ELSIF r.state IN('count_sent','counted') AND dr.created_at<=clock_timestamp()-interval '180 seconds'
    AND r.generation_call_id IS NULL AND r.authorization_id IS NULL AND dr.status='claimed' AND dr.dispatch_count=0
    AND count_q.state IN('sent','unknown_billable') AND count_q.sent_at IS NOT NULL
    AND NOT EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_attempts WHERE receipt_id=dr.id)
    AND NOT EXISTS(SELECT 1 FROM mission_narrative_internal.provider_authorizations WHERE receipt_id=dr.id)
   THEN
    PERFORM staff_ai_quota_private.unknown_billable(r.count_call_id);ch:=1;gh:=0;changed:=true;
    why:=CASE WHEN r.state='count_sent' THEN 'COUNT_ACK_TIMEOUT' ELSE 'COUNTED_NOT_DISPATCHED' END;
   ELSIF r.state IN('authorized','provider_started') AND r.authorization_id IS NOT NULL THEN
    SELECT * INTO STRICT z FROM mission_narrative_internal.provider_authorizations WHERE id=r.authorization_id AND receipt_id=dr.id FOR UPDATE;
    SELECT * INTO STRICT att FROM mission_narrative_internal.dispatch_attempts WHERE id=z.attempt_id AND receipt_id=dr.id FOR UPDATE;
    IF z.expires_at<=clock_timestamp() AND r.state='authorized' AND z.consumed_at IS NULL AND dr.status='authorized' AND dr.dispatch_count=0
     AND att.status='authorized' AND gen_q.state='reserved' AND gen_q.sent_at IS NULL
     AND NOT EXISTS(SELECT 1 FROM mission_narrative_internal.provider_authorizations WHERE receipt_id=dr.id AND consumed_at IS NOT NULL)
    THEN
     PERFORM staff_ai_quota_private.no_http(r.generation_call_id);why:='GENERATION_AUTHORIZATION_EXPIRED_NO_HTTP';changed:=true;ch:=1;gh:=0;
     UPDATE mission_narrative_internal.dispatch_attempts SET status='expired',actual_cost_usd=0,cost_basis='exact',finalized_at=clock_timestamp() WHERE id=att.id;
    ELSIF z.expires_at<=clock_timestamp() AND r.state='provider_started' AND z.consumed_at IS NOT NULL AND dr.status='provider_started' AND dr.dispatch_count=1
     AND att.status='provider_started' AND gen_q.state IN('sent','unknown_billable') AND gen_q.sent_at IS NOT NULL
    THEN
     PERFORM staff_ai_quota_private.unknown_billable(r.generation_call_id);why:='GENERATION_ACK_TIMEOUT';changed:=true;ch:=1;gh:=1;
     UPDATE mission_narrative_internal.dispatch_attempts SET status='unknown_billable',actual_cost_usd=NULL,cost_basis='upper_bound',finalized_at=clock_timestamp() WHERE id=att.id;
    END IF;
   END IF;
   IF changed THEN
    doc:=jsonb_build_object('schema_version',CASE WHEN why='READY_EXPIRED_NO_HTTP' THEN 'staff-editorial-preprovider-failure/1' ELSE 'staff-editorial-reconciliation/1' END,
     'run_id',r.id,'reason_code',why,'source_sha256',r.source_sha256,'request_sha256',r.request_sha256,'count_http_calls',ch,'generation_http_calls',gh,'provider_calls',gh,
     'outcome_uncertain',why IN('COUNT_ACK_TIMEOUT','GENERATION_ACK_TIMEOUT'),'count_reserved_usd',coalesce(count_q.reserved_usd,0),'generation_reserved_usd',CASE WHEN gh=1 THEN gen_q.reserved_usd ELSE 0 END,
     'charged_cost_usd',CASE WHEN ch=0 AND gh=0 THEN 0 ELSE NULL END);
    rs:=public.combat_v2_sha256(doc);
    UPDATE mission_narrative_internal.editorial_runs_v1 SET state=CASE WHEN why IN('COUNT_ACK_TIMEOUT','GENERATION_ACK_TIMEOUT') THEN 'uncertain' ELSE 'failed' END,
     reason_code=why,result=doc,result_sha256=rs,finalized_at=clock_timestamp() WHERE id=r.id RETURNING * INTO r;
    IF r.receipt_id IS NOT NULL THEN
     UPDATE mission_narrative_internal.dispatch_receipts SET status=CASE WHEN why IN('COUNT_ACK_TIMEOUT','GENERATION_ACK_TIMEOUT') THEN 'unknown_billable' ELSE 'failed' END,
      charged_cost_usd=CASE WHEN gh=1 THEN coalesce(upper_bound_cost_usd,gen_q.reserved_usd) ELSE 0 END,finalized_at=clock_timestamp(),updated_at=clock_timestamp() WHERE id=dr.id;
     INSERT INTO mission_narrative_internal.dispatch_audit(receipt_id,event_code,details) VALUES(dr.id,'editorial_reconciled',doc-'charged_cost_usd'||jsonb_build_object('result_sha256',rs));
    END IF;
    INSERT INTO mission_narrative_internal.editorial_audit_v1(run_id,event_code,details) VALUES(r.id,CASE WHEN why='READY_EXPIRED_NO_HTTP' THEN 'preprovider_rejected' ELSE 'reconciled' END,
     jsonb_build_object('source_sha256',r.source_sha256,'result_sha256',rs,'reason_code',why,'count_http_calls',ch,'generation_http_calls',gh));
   END IF;
  END IF;
  RETURN jsonb_build_object('schema_version','staff-editorial-reconcile/1','run_id',r.id,'state',r.state,'reconciled',changed,'reason_code',r.reason_code,'count_http_calls',ch,'generation_http_calls',gh);
 END IF;
 IF op='reject' THEN
  IF NOT mission_factory_owner.keys_exact_v2(p_command,ARRAY['operation','reason_code']) OR p_command->>'reason_code' NOT IN('request_build_failed','async_unavailable')
   OR r.state<>'ready' OR r.receipt_id IS NOT NULL OR r.count_call_id IS NOT NULL OR r.generation_call_id IS NOT NULL
   OR EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_receipts WHERE authority_receipt_id=r.id)
  THEN RAISE EXCEPTION 'E65_PREPROVIDER_REJECTION_DENIED';END IF;
  doc:=jsonb_build_object('schema_version','staff-editorial-preprovider-failure/1','run_id',r.id,'reason_code',p_command->>'reason_code','count_http_calls',0,'generation_http_calls',0,'provider_calls',0,'charged_cost_usd',0);
  rs:=public.combat_v2_sha256(doc);
  UPDATE mission_narrative_internal.editorial_runs_v1 SET state='failed',reason_code=p_command->>'reason_code',result=doc,result_sha256=rs,finalized_at=clock_timestamp() WHERE id=r.id;
  INSERT INTO mission_narrative_internal.editorial_audit_v1(run_id,event_code,details) VALUES(r.id,'preprovider_rejected',jsonb_build_object('result_sha256',rs,'source_sha256',r.source_sha256,'reason_code',p_command->>'reason_code','provider_calls',0));
  RETURN jsonb_build_object('schema_version','staff-editorial-finished/1','run_id',r.id,'state','failed','result_sha256',rs,'charged_cost_usd',0,'replayed',false);
 END IF;
 IF op='count_start' THEN
  IF NOT mission_factory_owner.keys_exact_v2(p_command,ARRAY['operation','request_text','request_sha256']) OR jsonb_typeof(p_command->'request_text')<>'string'
   OR octet_length(p_command->>'request_text')>(pol->>'max_request_bytes')::integer
   OR encode(extensions.digest(convert_to(p_command->>'request_text','UTF8'),'sha256'),'hex') IS DISTINCT FROM p_command->>'request_sha256'
  THEN RAISE EXCEPTION 'E65_REQUEST_SNAPSHOT_INVALID';END IF;
  IF r.request_sha256 IS NOT NULL THEN
   IF r.request_sha256<>p_command->>'request_sha256' OR r.request_text<>p_command->>'request_text' THEN RAISE EXCEPTION 'E65_REQUEST_CONFLICT';END IF;
   RETURN jsonb_build_object('schema_version','staff-editorial-count/1','run_id',r.id,'receipt_id',r.receipt_id,'call_id',r.count_call_id,'granted_now',false,'may_send_http',false,'request_text',r.request_text,'request_sha256',r.request_sha256,'model',pol->>'model');
  END IF;
  IF r.state<>'ready' OR http_used+2>(pol->>'max_http')::integer OR cost+2*(pol->>'upper_call_usd')::numeric>(pol->>'budget_usd')::numeric OR base_cost+cost+2*(pol->>'upper_call_usd')::numeric>(pol->>'total_budget_usd')::numeric
   OR (SELECT count(*) FROM mission_narrative_internal.editorial_runs_v1 WHERE campaign_id=c.id AND count_call_id IS NOT NULL)>=(pol->>'max_pairs')::integer
  THEN RAISE EXCEPTION 'E65_BUDGET_OR_STATE_DENIED';END IF;
  env:=jsonb_build_object('schema_version','staff-editorial-dispatch/1','run_id',r.id,'campaign_id',c.id,'actor_user',p_user,'case_no',r.case_no,'variant',r.variant,'stage','narration','source_sha256',r.source_sha256,'policy_sha256',c.policy_sha256,'request_sha256',p_command->>'request_sha256');
  fp:=public.combat_v2_sha256(env);authsha:=public.combat_v2_sha256(jsonb_build_object('envelope_sha256',fp,'source_sha256',r.source_sha256));
  INSERT INTO mission_narrative_internal.dispatch_receipts(master_session_id,authority_receipt_id,event_kind,renderer_version,request_key,request_fingerprint,authority_sha256,envelope,envelope_sha256)
   VALUES((r.source->>'master_session_id')::uuid,r.id,'mission_editorial_preview','mission-generic-editorial/1',r.request_key,fp,authsha,env,fp) RETURNING * INTO dr;
  qr:=staff_ai_quota_private.reserve('mission_editorial_preview',dr.id,2,c.id,pol->>'model',(pol->>'upper_call_usd')::numeric);
  PERFORM staff_ai_quota_private.mark_sent((qr->>'call_id')::uuid);
  UPDATE mission_narrative_internal.editorial_runs_v1 SET receipt_id=dr.id,count_call_id=(qr->>'call_id')::uuid,state='count_sent',request_text=p_command->>'request_text',request_sha256=p_command->>'request_sha256' WHERE id=r.id RETURNING * INTO r;
  INSERT INTO mission_narrative_internal.dispatch_audit(receipt_id,event_code,details) VALUES(dr.id,'editorial_count_sent',env||jsonb_build_object('call_id',r.count_call_id));
  RETURN jsonb_build_object('schema_version','staff-editorial-count/1','run_id',r.id,'receipt_id',r.receipt_id,'call_id',r.count_call_id,'granted_now',true,'may_send_http',true,'request_text',r.request_text,'request_sha256',r.request_sha256,'model',pol->>'model');
 ELSIF op='count_result' THEN
  IF NOT mission_factory_owner.keys_exact_v2(p_command,ARRAY['operation','outcome','input_tokens','http_status','response_sha256'])
   OR p_command->>'outcome' NOT IN('success','failed','unknown') OR coalesce(p_command->>'response_sha256','')!~'^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'E65_COUNT_RESULT_INVALID';END IF;
  IF r.state<>'count_sent' THEN RETURN jsonb_build_object('schema_version','staff-editorial-count-result/1','run_id',r.id,'state',r.state,'generation_allowed',r.state='counted');END IF;
  PERFORM staff_ai_quota_private.unknown_billable(r.count_call_id);
  cnt:=CASE WHEN p_command->>'outcome'='success' THEN (p_command->>'input_tokens')::integer ELSE NULL END;
  IF p_command->>'outcome'='success' AND (cnt IS NULL OR cnt<0 OR p_command->>'http_status'<>'200') THEN RAISE EXCEPTION 'E65_COUNT_MEASUREMENT_INVALID';END IF;
  overflow:=cnt IS NOT NULL AND cnt>(pol->>'max_input_tokens')::integer;
  IF overflow THEN
   SELECT * INTO STRICT count_q FROM staff_ai_quota_private.calls WHERE id=r.count_call_id;
   doc:=jsonb_build_object('schema_version','staff-editorial-count-failure/1','run_id',r.id,'reason_code','COUNT_INPUT_LIMIT','count_outcome','success','http_status',200,
    'input_tokens',cnt,'max_input_tokens',(pol->>'max_input_tokens')::integer,'request_sha256',r.request_sha256,'response_sha256',p_command->>'response_sha256',
    'count_http_calls',1,'generation_http_calls',0,'provider_calls',0,'outcome_uncertain',false,'count_reserved_usd',count_q.reserved_usd,'charged_cost_usd',NULL);
   rs:=public.combat_v2_sha256(doc);
  ELSIF cnt IS NULL THEN
   IF p_command->>'outcome'='failed' AND ((p_command->>'http_status')::integer IS NULL OR (p_command->>'http_status')::integer NOT BETWEEN 100 AND 599 OR p_command->>'http_status'='200') THEN RAISE EXCEPTION 'E65_DEFINITE_COUNT_HTTP_REQUIRED';END IF;
   SELECT * INTO STRICT count_q FROM staff_ai_quota_private.calls WHERE id=r.count_call_id;
   doc:=jsonb_build_object('schema_version','staff-editorial-count-failure/1','run_id',r.id,'count_outcome',p_command->>'outcome','http_status',p_command->'http_status',
    'request_sha256',r.request_sha256,'response_sha256',p_command->>'response_sha256','count_http_calls',1,'generation_http_calls',0,'provider_calls',0,
    'outcome_uncertain',p_command->>'outcome'='unknown','count_reserved_usd',count_q.reserved_usd,'charged_cost_usd',NULL);
   rs:=public.combat_v2_sha256(doc);
  END IF;
  UPDATE mission_narrative_internal.editorial_runs_v1 SET count_input_tokens=cnt,result=doc,result_sha256=rs,state=CASE WHEN overflow THEN 'failed' WHEN cnt IS NOT NULL THEN 'counted' WHEN p_command->>'outcome'='unknown' THEN 'uncertain' ELSE 'failed' END,
   reason_code=CASE WHEN overflow THEN 'COUNT_INPUT_LIMIT' WHEN cnt IS NULL THEN 'COUNT_'||upper(p_command->>'outcome') ELSE NULL END,finalized_at=CASE WHEN cnt IS NULL OR overflow THEN clock_timestamp() ELSE NULL END WHERE id=r.id RETURNING * INTO r;
  INSERT INTO mission_narrative_internal.dispatch_audit(receipt_id,event_code,details) VALUES(r.receipt_id,'editorial_count_result',p_command-'operation'||jsonb_build_object('run_id',r.id,'request_sha256',r.request_sha256,'result_sha256',r.result_sha256,'state',r.state,'count_http_calls',1,'generation_http_calls',0));
  IF cnt IS NULL OR overflow THEN UPDATE mission_narrative_internal.dispatch_receipts SET status=CASE WHEN r.state='uncertain' THEN 'unknown_billable' ELSE 'failed' END,finalized_at=clock_timestamp(),updated_at=clock_timestamp() WHERE id=r.receipt_id;END IF;
  RETURN jsonb_build_object('schema_version','staff-editorial-count-result/1','run_id',r.id,'state',r.state,'generation_allowed',r.state='counted');
 ELSIF op='authorize' THEN
  IF NOT mission_factory_owner.keys_exact_v2(p_command,ARRAY['operation']) OR r.state<>'counted' OR http_used+1>(pol->>'max_http')::integer OR cost+(pol->>'upper_call_usd')::numeric>(pol->>'budget_usd')::numeric OR base_cost+cost+(pol->>'upper_call_usd')::numeric>(pol->>'total_budget_usd')::numeric THEN RAISE EXCEPTION 'E65_GENERATION_DENIED';END IF;
  qr:=staff_ai_quota_private.reserve('mission_editorial_preview',r.receipt_id,1,c.id,pol->>'model',(pol->>'upper_call_usd')::numeric);
  core:=public.mission_narrative_attempt_reserve_internal(p_worker_token,r.receipt_id,300,NULL,NULL);
  IF core->>'status'<>'reserved' THEN RAISE EXCEPTION 'E65_CORE_RESERVE_DENIED';END IF;
  core:=public.mission_narrative_provider_authorize_internal(p_worker_token,r.receipt_id,(core->>'attempt_id')::uuid,core->>'lease_token');
  UPDATE mission_narrative_internal.editorial_runs_v1 SET state='authorized',generation_call_id=(qr->>'call_id')::uuid,authorization_id=(core->>'authorization_id')::uuid WHERE id=r.id;
  RETURN core||jsonb_build_object('schema_version','staff-editorial-authorized/1','run_id',r.id,'receipt_id',r.receipt_id,'request_sha256',r.request_sha256);
 ELSIF op='consume' THEN
  IF NOT mission_factory_owner.keys_exact_v2(p_command,ARRAY['operation','authorization_id','dispatch_token']) OR r.state<>'authorized' OR (p_command->>'authorization_id')::uuid<>r.authorization_id THEN RAISE EXCEPTION 'E65_CONSUME_DENIED';END IF;
  core:=public.mission_narrative_provider_consume_internal(p_worker_token,r.authorization_id,p_command->>'dispatch_token');
  PERFORM staff_ai_quota_private.mark_sent(r.generation_call_id);
  UPDATE mission_narrative_internal.editorial_runs_v1 SET state='provider_started' WHERE id=r.id;
  RETURN core||jsonb_build_object('schema_version','staff-editorial-consumed/1','run_id',r.id,'request_text',r.request_text,'request_sha256',r.request_sha256);
 END IF;
 -- Output custody and final accounting require the one real consumed authorization.
 SELECT * INTO STRICT z FROM mission_narrative_internal.provider_authorizations WHERE id=r.authorization_id AND receipt_id=r.receipt_id FOR UPDATE;
 IF (p_command->>'authorization_id')::uuid IS DISTINCT FROM z.id OR z.consumed_at IS NULL OR z.finalize_token_sha256 IS DISTINCT FROM mission_narrative_internal.token_sha(p_command->>'finalize_token') THEN RAISE EXCEPTION 'E65_FINALIZE_AUTHORITY_DENIED' USING ERRCODE='42501';END IF;
 IF op='retain' THEN
  IF NOT mission_factory_owner.keys_exact_v2(p_command,ARRAY['operation','authorization_id','finalize_token','raw_text','raw_sha256']) OR r.state NOT IN('provider_started','completed','failed','uncertain')
   OR jsonb_typeof(p_command->'raw_text')<>'string' OR octet_length(p_command->>'raw_text')>1048576
   OR encode(extensions.digest(convert_to(p_command->>'raw_text','UTF8'),'sha256'),'hex') IS DISTINCT FROM p_command->>'raw_sha256' THEN RAISE EXCEPTION 'E65_RAW_OUTPUT_INVALID';END IF;
  IF r.raw_sha256 IS NOT NULL AND (r.raw_sha256<>p_command->>'raw_sha256' OR r.raw_text<>p_command->>'raw_text') THEN RAISE EXCEPTION 'E65_RAW_OUTPUT_CONFLICT';END IF;
  IF r.raw_sha256 IS NULL THEN
   UPDATE mission_narrative_internal.editorial_runs_v1 SET raw_text=p_command->>'raw_text',raw_sha256=p_command->>'raw_sha256',retained_at=clock_timestamp() WHERE id=r.id;
   INSERT INTO mission_narrative_internal.dispatch_audit(receipt_id,event_code,details) VALUES(r.receipt_id,'editorial_output_retained',jsonb_build_object('run_id',r.id,'raw_sha256',p_command->>'raw_sha256'));
  END IF;
  RETURN jsonb_build_object('schema_version','staff-editorial-retained/1','run_id',r.id,'raw_sha256',p_command->>'raw_sha256','replayed',r.raw_sha256 IS NOT NULL);
 ELSIF op='finish' THEN
  IF NOT mission_factory_owner.keys_exact_v2(p_command,ARRAY['operation','authorization_id','finalize_token','result','input_tokens','output_tokens','reasoning_tokens','outcome']) OR p_command->>'outcome' NOT IN('success','failed','unknown') THEN RAISE EXCEPTION 'E65_FINISH_SHAPE';END IF;
  outcome:=p_command->>'outcome';doc:=p_command->'result';rs:=public.combat_v2_sha256(doc);
  IF r.state IN('completed','failed','uncertain') THEN
   IF r.result_sha256 IS DISTINCT FROM rs THEN RAISE EXCEPTION 'E65_FINISH_CONFLICT';END IF;
   RETURN jsonb_build_object('schema_version','staff-editorial-finished/1','run_id',r.id,'state',r.state,'result_sha256',r.result_sha256,'charged_cost_usd',(SELECT charged_cost_usd FROM mission_narrative_internal.dispatch_receipts WHERE id=r.receipt_id),'replayed',true);
  END IF;
  IF r.state<>'provider_started' THEN RAISE EXCEPTION 'E65_FINISH_STATE';END IF;
  IF outcome='unknown' THEN
   PERFORM staff_ai_quota_private.unknown_billable(r.generation_call_id);cost:=NULL;
  ELSE
   it:=(p_command->>'input_tokens')::integer;ot:=(p_command->>'output_tokens')::integer;rt:=(p_command->>'reasoning_tokens')::integer;
   IF r.raw_sha256 IS NULL OR it IS NULL OR ot IS NULL OR least(it,ot)<0 OR (rt IS NOT NULL AND rt<0) OR it>(pol->>'max_input_tokens')::integer OR ot>(pol->>'max_output_tokens')::integer OR (rt IS NOT NULL AND rt>ot) OR jsonb_typeof(doc)<>'object' THEN RAISE EXCEPTION 'E65_USAGE_OR_OUTPUT_CUSTODY_INVALID';END IF;
   qr:=staff_ai_quota_private.settle(r.generation_call_id,it,ot);cost:=(qr->>'charged_usd')::numeric;
  END IF;
  UPDATE mission_narrative_internal.dispatch_attempts SET status=CASE WHEN outcome='unknown' THEN 'unknown_billable' ELSE 'success' END,
   actual_cost_usd=cost,cost_basis=CASE WHEN outcome='unknown' THEN 'upper_bound' ELSE 'exact' END,input_tokens=it,output_tokens=ot,reasoning_tokens=rt,total_tokens=it+ot,finalized_at=clock_timestamp() WHERE id=z.attempt_id;
  UPDATE mission_narrative_internal.dispatch_receipts SET status=CASE WHEN outcome='unknown' THEN 'unknown_billable' ELSE 'success' END,
   charged_cost_usd=coalesce(cost,upper_bound_cost_usd),finalized_at=clock_timestamp(),updated_at=clock_timestamp() WHERE id=r.receipt_id;
  UPDATE mission_narrative_internal.editorial_runs_v1 SET state=CASE outcome WHEN 'success' THEN 'completed' WHEN 'failed' THEN 'failed' ELSE 'uncertain' END,
   result=doc,result_sha256=rs,reason_code=CASE WHEN outcome='success' THEN NULL ELSE 'WRITER_'||upper(outcome) END,finalized_at=clock_timestamp() WHERE id=r.id RETURNING * INTO r;
  INSERT INTO mission_narrative_internal.dispatch_audit(receipt_id,event_code,details) VALUES(r.receipt_id,'editorial_finalized',jsonb_build_object('run_id',r.id,'source_sha256',r.source_sha256,'request_sha256',r.request_sha256,'raw_sha256',r.raw_sha256,'result_sha256',rs,'state',r.state,'outcome',outcome,'charged_cost_usd',cost));
  RETURN jsonb_build_object('schema_version','staff-editorial-finished/1','run_id',r.id,'state',r.state,'result_sha256',rs,'charged_cost_usd',cost,'replayed',false);
 END IF;
 RAISE EXCEPTION 'E65_OPERATION_UNREACHABLE';
END $function$
